#!/usr/bin/env node
/**
 * Regenerates docs/src/lib/utils/markdown_bundle.generated.ts from docs/content/.
 * Run from repo root or docs/: node docs/scripts/generate-doc-markdown-bundle.mjs
 */
import { readdirSync, readFileSync, writeFileSync, statSync } from 'node:fs'
import { join, relative, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const docsRoot = join(dirname(fileURLToPath(import.meta.url)), '..')
const contentDir = join(docsRoot, 'content')
const outFile = join(docsRoot, 'src/lib/utils/markdown_bundle.generated.ts')

function walkMarkdown(dir, acc = []) {
  for (const name of readdirSync(dir)) {
    const full = join(dir, name)
    if (statSync(full).isDirectory()) {
      walkMarkdown(full, acc)
      continue
    }
    if (name.endsWith('.md')) acc.push(full)
  }
  return acc
}

const files = walkMarkdown(contentDir).sort()
const entries = files.map((file) => {
  const rel = relative(contentDir, file).replace(/\\/g, '/')
  const key = rel.replace(/\.md$/, '')
  const raw = readFileSync(file, 'utf8')
  return `  ${JSON.stringify(key)}: ${JSON.stringify(raw)}`
})

const body = `// AUTO-GENERATED by scripts/generate-doc-markdown-bundle.mjs - do not edit.
export const MARKDOWN_BUNDLE: Record<string, string> = {
${entries.join(',\n')},
}

export function getBundledMarkdown(
  lang: string,
  category: string,
  slug: string
): string | null {
  return MARKDOWN_BUNDLE[\`\${lang}/\${category}/\${slug}\`] ?? null
}
`

writeFileSync(outFile, body, 'utf8')
console.log(`Wrote ${entries.length} docs → ${relative(docsRoot, outFile)}`)
